      Check(entries.Where(e=>e.Id.StartsWith("rl-")&&!e.ProjectOnly&&!e.DiscoverExecutable).Count()==27,"twenty-seven separately audited RecompLauncher packages");
      Check(entries.Where(e=>e.Platform=="Wii U").All(e=>!e.ProjectOnly&&e.PlayNames.Length==1),"all four reported Wii U profiles have automatic downloads");
      foreach(string id in new[]{"rl-zeldawwhdrecomp","rl-nsmbu-recomp"}){var setup=entries.First(e=>e.Id==id);Check(setup.ConfigurationArguments=="--setup"&&setup.ConfigNames.SequenceEqual(setup.PlayNames),"Wii U configuration reopens original setup "+id);var audited=PortCatalog.BundledRelease(setup);Reject(()=>PortCatalog.ParseRelease(setup,new JavaScriptSerializer().Serialize(new{tag_name="arm-fixture",html_url=setup.ProjectUrl+"/releases/tag/fixture",draft=false,prerelease=false,assets=new[]{new{name=audited.AssetName.Replace("x86_64","arm64"),size=100,browser_download_url=setup.ProjectUrl+"/releases/download/fixture/arm64.zip"}}})),"Wii U ARM64 package rejected "+id);}
      Check(entries.First(e=>e.Id=="rl-botw-native").PlayNames.Single()=="BotWLauncher.exe","BotW uses original launcher instead of unprepared runtime or installer");
      Check(entries.First(e=>e.Repository=="VantageEX/infamous-first-light-pc").Arguments=="--play","First Light direct play uses documented launcher switch");
      Check(!entries.Any(e=>new[]{"SpeedBreakerProject/speedbreaker","Mabec-games/F-ZERO-GLINUX","HekamiAeon/Sakura-Wars-PS4RT","jillsandwich1998/reGH2"}.Contains(e.Repository)),"non-Windows entries excluded");
      var zelda=entries.First(e=>e.Id=="rl-zelda64recomp");var zeldaJson=new JavaScriptSerializer().Serialize(new{tag_name="fixture",html_url=zelda.ProjectUrl+"/releases/tag/fixture",draft=false,prerelease=false,assets=new[]{new{name="Zelda64Recompiled-fixture-Windows-ARM64.zip",size=100,browser_download_url=zelda.ProjectUrl+"/releases/download/fixture/Zelda64Recompiled-fixture-Windows-ARM64.zip"}}});Reject(()=>PortCatalog.ParseRelease(zelda,zeldaJson),"new ARM64 naming cannot replace audited x64 package");
      foreach(string origin in new[]{"Nintendo 64","GameCube","Wii","Wii U","Super Nintendo","Game Boy","Game Boy Advance","Nintendo DS","PlayStation","PlayStation 2","PSP","Dreamcast"}){var legacyPlatform=Store.Parse("{\"Version\":1,\"Games\":[{\"Id\":\"platform\",\"Name\":\"Fixture\",\"Executable\":\"custom.exe\",\"Platform\":\""+origin+"\"}]}");Check(legacyPlatform.Games[0].Platform==origin,"new origin persists in library "+origin);}
      var gameA=new Game{Name="Halo",Executable="halo.exe",Platform="Xbox",Favorite=true};var gameB=new Game{Name="Sonic",Executable="sonic.exe",Platform="Xbox 360"};
      Check(Platforms.Filter(new[]{gameA,gameB},"Xbox","",false).Count==1,"exact platform filter does not mix Xbox and Xbox 360");
      Check(Platforms.Filter(new[]{gameA,gameB},Platforms.All[0],"sonic",false).Single()==gameB,"search combines with platform");
      Check(Platforms.Filter(new[]{gameA,gameB},"Xbox 360","",true).Count==0,"favorites combines with platform");
      var old=Store.Parse("{\"Version\":1,\"Games\":[{\"Id\":\"old\",\"Name\":\"God of War III\",\"Executable\":\"C:\\\\gow3\\\\Play God of War III.exe\"}]}");Check(old.Games[0].Platform=="PlayStation 4","legacy known ports retain original platform");
      Check(Platforms.Resolve(new Game{Name="Unknown",Executable="custom.exe"})=="Outras","unknown manual games not mislabeled PlayStation");
      var manual=entries.First(e=>e.ProjectOnly);using(var catalog=new PortCatalog(new RateLimitHandler()))Reject(()=>catalog.Latest(manual,CancellationToken.None).GetAwaiter().GetResult(),"project-only entries never invoke installer query");
      return checks;
    }
    class FixtureHandler:HttpMessageHandler {
      readonly byte[] bytes;public FixtureHandler(byte[] content){bytes=content;}
      protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){RequestMessage=request,Content=new ByteArrayContent(bytes)});}
    }
    class RateLimitHandler:HttpMessageHandler {
      public int Count;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Count++;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.Forbidden){RequestMessage=request,Content=new StringContent("rate limited")});}
    }
